// Generated by forge. The types engine for TypeScript (SPECS §15): a daemon that keeps
// the project's own TypeScript running for one repository and answers the hooks' type
// questions through a FIFO: TypeScript 7 or later through its language server
// (tsc --lsp), TypeScript 5 and 6 through their tsserver. Started by forge_types_up as
//   bun types_typescript.mjs <root> <state-dir>
// It detaches (its own session), then writes "ready <server> <version>" (or
// "failed <reason>") to the FIFO <state-dir>/started, and loads the project's
// tsconfig projects in the background (questions go first). The protocol on
// <state-dir>/in is the Python engine's (types_python.py): "changed<TAB><path>",
// "stop", "restart", or the absolute path of a question directory (req: ast-grep
// matches; reply: the matches whose forge_where holds, "error<TAB>..." lines, "end").
// Node-compatible: no Bun-only API.
import { execFileSync, spawn } from "node:child_process";
import fs from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import process from "node:process";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = fs.realpathSync(process.argv[2]);
const STATE = process.argv[3];
const IDLE = Number(process.env.FORGE_TYPES_IDLE ?? 1800) * 1000;
const logFile = fs.openSync(path.join(STATE, "log"), "a");
const log = (...a) => fs.writeSync(logFile, `${new Date().toISOString().slice(11, 19)} ${a.join(" ")}\n`);

const uri = (p) => pathToFileURL(fs.existsSync(p) ? fs.realpathSync(p) : p).href;
const pathOf = (u) => (u.startsWith("file://") ? fileURLToPath(u) : u);

/** The LSP position (UTF-16 columns, as JS strings count) of a string index. */
function position(text, index) {
  let line = 0;
  for (let i = text.indexOf("\n"); i >= 0 && i < index; i = text.indexOf("\n", i + 1)) line++;
  return { line, character: index - (text.lastIndexOf("\n", index - 1) + 1) };
}
function indexOf(text, pos) {
  let i = 0;
  for (let l = 0; l < pos.line; l++) i = text.indexOf("\n", i) + 1;
  return i + pos.character;
}

// ---------------------------------------------------------------- the language servers

/**
 * The project's own TypeScript decides the server (§15.2): TypeScript 7 or later, its
 * language server (tsc --lsp); TypeScript 5 and 6, its tsserver. Both are driven
 * through the same small interface: show(file, text), sync(file), changed(file),
 * typeDefinition(file, pos) and definition(file, pos), positions and results as LSP
 * (0-based lines, UTF-16 columns; results [{uri, pos}]).
 */
function projectTypeScript() {
  let pkg;
  try {
    pkg = createRequire(path.join(ROOT, "package.json")).resolve("typescript/package.json");
  } catch {
    throw new Error("the project has no typescript package (node_modules/typescript): install the project's dependencies");
  }
  const version = JSON.parse(fs.readFileSync(pkg, "utf8")).version;
  return { dir: path.dirname(pkg), version, major: Number(version.split(".")[0]) };
}

class Base {
  constructor() {
    this.texts = new Map();
  }
  /** The file as it is on disk; returns its text. */
  sync(file) {
    const text = fs.readFileSync(file, "utf8");
    if (this.texts.get(file) !== text) {
      this.show(file, text);
      this.texts.set(file, text);
    }
    return text;
  }
  exited() {
    log("server exited");
    process.exit(3);
  }
}

/** TypeScript 7: the native compiler's language server, LSP over stdio. */
class Lsp extends Base {
  constructor(ts) {
    super();
    this.proc = spawn(process.execPath, [path.join(ts.dir, "bin", "tsc"), "--lsp", "--stdio"], { cwd: ROOT, stdio: ["pipe", "pipe", logFile] });
    this.proc.on("exit", () => this.exited());
    this.buf = Buffer.alloc(0);
    this.next = 0;
    this.waiting = new Map();
    this.versions = new Map();
    this.proc.stdout.on("data", (d) => this.read(d));
  }
  read(d) {
    this.buf = Buffer.concat([this.buf, d]);
    for (;;) {
      const sep = this.buf.indexOf("\r\n\r\n");
      if (sep < 0) return;
      const len = Number(/content-length: *(\d+)/i.exec(this.buf.subarray(0, sep).toString())[1]);
      if (this.buf.length < sep + 4 + len) return;
      const msg = JSON.parse(this.buf.subarray(sep + 4, sep + 4 + len).toString());
      this.buf = this.buf.subarray(sep + 4 + len);
      if (msg.method && msg.id !== undefined) {
        // a request from the server (configuration, registrations): answer with defaults
        const items = msg.params?.items;
        this.send({ jsonrpc: "2.0", id: msg.id, result: items ? items.map(() => null) : null });
      } else if (msg.id !== undefined) {
        this.waiting.get(msg.id)?.(msg.result);
        this.waiting.delete(msg.id);
      }
    }
  }
  send(msg) {
    const body = Buffer.from(JSON.stringify(msg));
    this.proc.stdin.write(Buffer.concat([Buffer.from(`Content-Length: ${body.length}\r\n\r\n`), body]));
  }
  request(method, params) {
    const id = ++this.next;
    return new Promise((resolve) => {
      this.waiting.set(id, resolve);
      this.send({ jsonrpc: "2.0", id, method, params });
    });
  }
  notify(method, params) {
    this.send({ jsonrpc: "2.0", method, params });
  }
  async start() {
    const info = await this.request("initialize", {
      processId: process.pid,
      rootUri: uri(ROOT),
      workspaceFolders: [{ uri: uri(ROOT), name: "root" }],
      capabilities: {
        general: { positionEncodings: ["utf-16"] },
        textDocument: { typeDefinition: { linkSupport: true }, definition: { linkSupport: true } },
        workspace: { configuration: true, workspaceFolders: true },
      },
    });
    this.notify("initialized", {});
    return `${info?.serverInfo?.name ?? "tsc"} ${info?.serverInfo?.version ?? ""}`.trim();
  }
  show(file, text) {
    const u = uri(file);
    const v = (this.versions.get(u) ?? 0) + 1;
    this.versions.set(u, v);
    if (v === 1) this.notify("textDocument/didOpen", { textDocument: { uri: u, languageId: languageId(file), version: v, text } });
    else this.notify("textDocument/didChange", { textDocument: { uri: u, version: v }, contentChanges: [{ text }] });
  }
  changed(file) {
    if (this.versions.has(uri(file))) {
      if (fs.existsSync(file)) this.sync(file);
      return;
    }
    this.notify("workspace/didChangeWatchedFiles", { changes: [{ uri: uri(file), type: fs.existsSync(file) ? 2 : 3 }] });
  }
  async locations(method, file, pos) {
    const r = await this.request(`textDocument/${method}`, { textDocument: { uri: uri(file) }, position: pos });
    return asArray(r).map((l) => ({ uri: l.targetUri ?? l.uri, pos: (l.targetSelectionRange ?? l.targetRange ?? l.range).start }));
  }
  typeDefinition(file, pos) {
    return this.locations("typeDefinition", file, pos);
  }
  definition(file, pos) {
    return this.locations("definition", file, pos);
  }
}

/** TypeScript 5 and 6: the project's tsserver, its own protocol over stdio (1-based lines and offsets). */
class TsServer extends Base {
  constructor(ts) {
    super();
    this.version = ts.version;
    this.proc = spawn(process.execPath, [path.join(ts.dir, "lib", "tsserver.js"), "--disableAutomaticTypingAcquisition", "--suppressDiagnosticEvents"], {
      cwd: ROOT,
      stdio: ["pipe", "pipe", logFile],
    });
    this.proc.on("exit", () => this.exited());
    this.buf = Buffer.alloc(0);
    this.seq = 0;
    this.waiting = new Map();
    this.open = new Set();
    this.shown = new Map();
    this.proc.stdout.on("data", (d) => this.read(d));
  }
  read(d) {
    this.buf = Buffer.concat([this.buf, d]);
    for (;;) {
      const sep = this.buf.indexOf("\r\n\r\n");
      if (sep < 0) return;
      const len = Number(/content-length: *(\d+)/i.exec(this.buf.subarray(0, sep).toString())[1]);
      if (this.buf.length < sep + 4 + len) return;
      const msg = JSON.parse(this.buf.subarray(sep + 4, sep + 4 + len).toString());
      this.buf = this.buf.subarray(sep + 4 + len);
      if (msg.type === "response") {
        this.waiting.get(msg.request_seq)?.(msg.success ? msg.body : undefined);
        this.waiting.delete(msg.request_seq);
      }
    }
  }
  /** A command; with an answer, a promise of its body. */
  command(command, args, answer = true) {
    const seq = ++this.seq;
    this.proc.stdin.write(`${JSON.stringify({ seq, type: "request", command, arguments: args })}\n`);
    if (!answer) return undefined;
    return new Promise((resolve) => this.waiting.set(seq, resolve));
  }
  async start() {
    await this.command("configure", { preferences: {}, hostInfo: "forge" });
    return `tsserver ${this.version}`;
  }
  show(file, text) {
    if (!this.open.has(file)) {
      this.command("open", { file, fileContent: text, scriptKindName: scriptKind(file), projectRootPath: ROOT }, false);
      this.open.add(file);
    } else {
      // only the span that differs (common prefix and suffix kept): tsserver reparses less
      const old = this.shown.get(file);
      let a = 0;
      while (a < old.length && a < text.length && old[a] === text[a]) a++;
      let b = 0;
      while (b < old.length - a && b < text.length - a && old[old.length - 1 - b] === text[text.length - 1 - b]) b++;
      const at = (i) => {
        const p = position(old, i);
        return { line: p.line + 1, offset: p.character + 1 };
      };
      const change = { start: at(a), end: at(old.length - b), newText: text.slice(a, text.length - b) };
      this.command("updateOpen", { changedFiles: [{ fileName: file, textChanges: [change] }] }, false);
    }
    this.shown.set(file, text);
  }
  changed(file) {
    if (this.open.has(file)) {
      if (fs.existsSync(file)) this.sync(file);
      return;
    }
    // a file the server reads from disk: opening and closing it makes it read it again
    if (fs.existsSync(file)) {
      this.command("open", { file, projectRootPath: ROOT }, false);
      this.command("close", { file }, false);
    }
  }
  async locations(command, file, pos) {
    const body = await this.command(command, { file, line: pos.line + 1, offset: pos.character + 1 });
    return asArray(body).map((s) => ({ uri: pathToFileURL(s.file).href, pos: { line: s.start.line - 1, character: s.start.offset - 1 } }));
  }
  typeDefinition(file, pos) {
    return this.locations("typeDefinition", file, pos);
  }
  definition(file, pos) {
    return this.locations("definition", file, pos);
  }
}

const languageId = (file) =>
  /\.[cm]?tsx?$/.test(file) ? (file.endsWith("x") ? "typescriptreact" : "typescript") : file.endsWith("x") ? "javascriptreact" : "javascript";
const scriptKind = (file) => ({ typescript: "TS", typescriptreact: "TSX", javascript: "JS", javascriptreact: "JSX" })[languageId(file)];

// ---------------------------------------------------------------- declarations

/**
 * [package, module] of a declaration file: the npm package of the innermost
 * node_modules directory (@types/x counts as x, @types/a__b as @a/b) and the file's
 * path in it without its extension; TypeScript's own lib files (lib.*.d.ts) are
 * package "typescript"; [null, path] for the project's own files.
 */
function declaredIn(file) {
  const p = file.split(path.sep).join("/");
  const i = p.lastIndexOf("/node_modules/");
  const strip = (s) => s.replace(/(\.d)?\.[cm]?[jt]sx?$/, "");
  if (i < 0) {
    const real = fs.existsSync(file) ? fs.realpathSync(file) : file;
    return real.startsWith(ROOT + "/") ? [null, strip(real.slice(ROOT.length + 1))] : [null, null];
  }
  // TypeScript's own lib files (shipped in typescript or its native @typescript/* package)
  const lib = /\/node_modules\/(typescript|@typescript\/[^/]+)\/lib\/(lib\.[^/]*)\.d\.ts$/.exec(p);
  if (lib) return ["typescript", `typescript/lib/${lib[2]}`];
  const segs = p.slice(i + "/node_modules/".length).split("/");
  let pkg = segs[0].startsWith("@") ? `${segs[0]}/${segs[1]}` : segs[0];
  const rest = segs.slice(pkg.split("/").length).join("/");
  if (pkg.startsWith("@types/")) {
    const t = pkg.slice(7);
    pkg = t.includes("__") ? `@${t.replace("__", "/")}` : t;
  }
  return [pkg, `${pkg}/${strip(rest)}`];
}

const WORD = /[A-Za-z_$][\w$]*/y;
const KEYWORDS = new Set(["export", "declare", "default", "abstract", "class", "interface", "type", "enum", "const", "let", "var", "function", "namespace", "module"]);

function readText(file) {
  try {
    return fs.readFileSync(file, "utf8");
  } catch {
    return undefined;
  }
}

/** The index of the first character at or after <i> that is not whitespace or a comment. */
function skipTrivia(text, i) {
  for (;;) {
    while (i < text.length && /\s/.test(text[i])) i++;
    if (text.startsWith("//", i)) {
      const n = text.indexOf("\n", i);
      i = n < 0 ? text.length : n + 1;
    } else if (text.startsWith("/*", i)) {
      const n = text.indexOf("*/", i + 2);
      i = n < 0 ? text.length : n + 2;
    } else return i;
  }
}

/** The index just past the string literal starting at <i> (its quote). */
function skipString(text, i) {
  const q = text[i];
  for (let j = i + 1; j < text.length; j++) {
    if (text[j] === "\\") j++;
    else if (text[j] === q) return j + 1;
  }
  return text.length;
}

/**
 * The name of the type alias whose body holds <index>, the start of an anonymous type
 * (an object type literal, a function or tuple type): `type UseFormWatch<T> = { … }`
 * gives UseFormWatch. The servers point the type definition of such a type at the
 * literal, which has no name of its own. Undefined when no alias declares it (an inline
 * type annotation).
 */
function enclosingAlias(text, index) {
  const heads = [...text.slice(0, index).matchAll(/\btype\s+([A-Za-z_$][\w$]*)/g)];
  for (let h = heads.length - 1; h >= 0; h--) {
    const head = heads[h];
    // past the name and its type parameters (balanced <>, where => is not a closing >)
    let i = skipTrivia(text, head.index + head[0].length);
    if (text[i] === "<") {
      let depth = 0;
      for (; i < index; i++) {
        if (text[i] === "=" && text[i + 1] === ">") i++;
        else if (text[i] === "<") depth++;
        else if (text[i] === ">" && --depth === 0) break;
      }
      i = skipTrivia(text, i + 1);
    }
    if (text[i] !== "=" || text[i + 1] === ">" || i >= index) continue;
    // the alias's statement goes on to a ; at depth 0 (or the end of the enclosing block)
    let depth = 0;
    let ended = false;
    for (let j = i + 1; j < index && !ended; ) {
      const k = skipTrivia(text, j);
      if (k !== j) {
        j = k;
        continue;
      }
      const c = text[j];
      if (c === '"' || c === "'" || c === "`") j = skipString(text, j);
      else {
        if ("([{".includes(c)) depth++;
        else if (")]}".includes(c)) ended = --depth < 0;
        else if (c === ";" && depth === 0) ended = true;
        j++;
      }
    }
    if (!ended) return head[1];
  }
  return undefined;
}

/**
 * The declared name at <index> (keywords and comments skipped): { name, end }, with end
 * where a class or interface header's heritage clauses start; an anonymous type gets the
 * name of the alias declaring it, and no heritage (end undefined).
 */
function nameAt(text, index) {
  for (let i = skipTrivia(text, index); i < text.length; i = skipTrivia(text, i)) {
    WORD.lastIndex = i;
    const m = WORD.exec(text);
    if (!m) {
      const name = enclosingAlias(text, i);
      return name ? { name, end: undefined } : undefined;
    }
    if (!KEYWORDS.has(m[0])) return { name: m[0], end: i + m[0].length };
    i += m[0].length;
  }
  return undefined;
}

/**
 * The positions of the names a class or interface header extends or implements
 * (at depth 0 of <>, (), []; the last segment of a qualified name), from the end of
 * its name to its body.
 */
function heritage(text, from) {
  const out = [];
  let depth = 0;
  let list = false;
  for (let i = from; i < text.length; ) {
    const c = text[i];
    if (c === "/" && text[i + 1] === "/") {
      i = text.indexOf("\n", i);
      if (i < 0) break;
      continue;
    }
    if (c === "/" && text[i + 1] === "*") {
      i = text.indexOf("*/", i) + 2;
      continue;
    }
    if (c === "=" && text[i + 1] === ">") {
      i += 2;
      continue;
    }
    if ("<([{".includes(c)) {
      if (c === "{" && depth === 0) break;
      depth++;
      i++;
      continue;
    }
    if (">)]}".includes(c)) {
      depth--;
      i++;
      continue;
    }
    if ((c === ";" || c === "=") && depth === 0) break;
    WORD.lastIndex = i;
    const m = WORD.exec(text);
    if (!m) {
      i++;
      continue;
    }
    if (depth === 0 && (m[0] === "extends" || m[0] === "implements")) list = true;
    else if (depth === 0 && list) {
      let last = i;
      let j = i + m[0].length;
      while (text[j] === "." && /[A-Za-z_$]/.test(text[j + 1] ?? "")) {
        WORD.lastIndex = j + 1;
        const n = WORD.exec(text);
        last = j + 1;
        j = j + 1 + n[0].length;
      }
      out.push(last);
      i = j;
      continue;
    }
    i += m[0].length;
  }
  return out;
}

class Types {
  constructor(server) {
    this.server = server;
    this.cache = new Map();
  }
  /** The declarations [package, module, name] of the type declared at loc and of the classes and interfaces it extends or implements, transitively. */
  async hierarchy(loc) {
    const key = `${loc.uri}:${loc.pos.line}:${loc.pos.character}`;
    if (this.cache.has(key)) return this.cache.get(key);
    const out = new Map();
    const seen = new Set();
    const todo = [loc];
    while (todo.length && seen.size < 64) {
      const l = todo.pop();
      const k = `${l.uri}:${l.pos.line}:${l.pos.character}`;
      if (seen.has(k)) continue;
      seen.add(k);
      const file = pathOf(l.uri);
      const [pkg, mod] = declaredIn(file);
      const text = readText(file);
      if (text === undefined) continue;
      const at = nameAt(text, indexOf(text, l.pos));
      if (!at) continue;
      out.set(`${pkg}\0${mod}\0${at.name}`, [pkg, mod, at.name]);
      const bases = at.end === undefined ? [] : heritage(text, at.end);
      const defs = await Promise.all(
        bases.map((b) => this.server.definition(file, position(text, b))),
      );
      for (const d of defs) todo.push(...d);
    }
    const value = [...out.values()];
    if (!pathOf(loc.uri).startsWith(ROOT + "/") || loc.uri.includes("/node_modules/")) this.cache.set(key, value);
    return value;
  }
  /**
   * wanted: [[match index, variable, start byte, end byte]]. Returns a Map
   * "index\0variable" -> declarations, from the type the server infers for each
   * expression: the file is shown to the server with each expression wrapped as
   * ({__forge_t<i>: (<expr>)}).__forge_t<i>, in memory only, and the type definition of
   * that property is asked.
   */
  async check(file, wanted) {
    const text = fs.readFileSync(file, "utf8");
    const raw = Buffer.from(text, "utf8");
    const ranges = [];
    const slot = wanted.map(([, , s, e]) => {
      const r = [raw.subarray(0, s).toString("utf8").length, raw.subarray(0, e).toString("utf8").length];
      let i = ranges.findIndex(([a, b]) => a === r[0] && b === r[1]);
      if (i < 0) i = ranges.push(r) - 1;
      return i;
    });
    // inserts: at each start the opening, at each end the closing; at the same offset,
    // closings first (inner first), then openings (outer first)
    const events = [];
    ranges.forEach(([s, e], n) => {
      events.push([s, 1, -(e - s), n, `({__forge_t${n}: (`]);
      events.push([e, 0, e - s, n, `)}).__forge_t${n}`]);
    });
    events.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2] || a[3] - b[3]);
    let overlay = "";
    let last = 0;
    const anchors = [];
    for (const [off, kind, , n, piece] of events) {
      overlay += text.slice(last, off);
      last = off;
      if (kind === 0) anchors[n] = overlay.length + piece.length - 2; // inside the property name
      overlay += piece;
    }
    overlay += text.slice(last);
    // the server keeps this version until the file changes: the wrapping binds no name, so
    // what other files see of this one is unchanged (one program update per question)
    this.server.show(file, overlay);
    this.server.texts.set(file, overlay);
    const results = await Promise.all(ranges.map((_, n) => this.server.typeDefinition(file, position(overlay, anchors[n]))));
    const perRange = [];
    for (const r of results) {
      const decls = [];
      for (const l of r) decls.push(...(await this.hierarchy(l)));
      // any and unknown have no declaration: the checker does not know the type
      perRange.push({ decls, unknown: decls.length === 0 });
    }
    return new Map(wanted.map((w, n) => [`${w[0]}\0${w[1]}`, perRange[slot[n]]]));
  }
}

const asArray = (r) => (Array.isArray(r) ? r : r ? [r] : []);

// ---------------------------------------------------------------- constraints

const listed = (v) => (v === undefined ? undefined : Array.isArray(v) ? v : [v]);

/**
 * A type spec ({package, module, name, unknown}) holds when one declaration of the type
 * (a union member, or a supertype of one) is declared there with that name; a type the
 * checker does not know (any, unknown) holds only with unknown: match.
 */
function satisfies({ decls, unknown }, spec) {
  if (unknown) return spec.unknown === "match";
  const pkgs = listed(spec.package);
  const mods = listed(spec.module);
  const names = listed(spec.name);
  return decls.some(
    ([pkg, mod, name]) =>
      (!pkgs || pkgs.includes(pkg)) && (!mods || mods.some((m) => mod === m || (mod ?? "").startsWith(`${m}/`))) && (!names || names.includes(name)),
  );
}
const holds = (decls, cond) => (cond.not ? !holds(decls, cond.not) : satisfies(decls, cond.type));

async function answer(types, matches) {
  const byFile = new Map();
  matches.forEach((m, n) => {
    const where = m.metadata?.forge_where ?? {};
    const single = m.metaVariables?.single ?? {};
    for (const v of Object.keys(where)) {
      if (!single[v]) continue;
      const b = single[v].range.byteOffset;
      if (!byFile.has(m.file)) byFile.set(m.file, []);
      byFile.get(m.file).push([n, v, b.start, b.end]);
    }
  });
  const found = new Map();
  for (const [f, wanted] of byFile) for (const [k, d] of await types.check(path.join(ROOT, f), wanted)) found.set(k, d);
  return matches.flatMap((m, n) =>
    Object.entries(m.metadata?.forge_where ?? {}).every(([v, cond]) => !found.has(`${n}\0${v}`) || holds(found.get(`${n}\0${v}`), cond)) ? [n] : [],
  );
}

// ---------------------------------------------------------------- the FIFO loop

function reply(dir, lines) {
  let fd;
  try {
    fd = fs.openSync(path.join(dir, "reply"), fs.constants.O_WRONLY | fs.constants.O_NONBLOCK);
  } catch {
    return; // nobody waits for it
  }
  const data = Buffer.from([...lines, "end"].map((l) => `${l}\n`).join(""));
  for (let off = 0; off < data.length; ) {
    try {
      off += fs.writeSync(fd, data, off);
    } catch (e) {
      if (e.code !== "EAGAIN") break;
    }
  }
  fs.closeSync(fd);
}

/** Removes the daemon's files, unless another daemon took the state directory over. */
function cleanup() {
  if (readText(path.join(STATE, "pid"))?.trim() !== String(process.pid)) return;
  for (const n of ["ready", "pid", "in", "loading"]) fs.rmSync(path.join(STATE, n), { force: true });
}

/** Tells the starter (waiting on <state>/started) how the start went. */
function started(line) {
  try {
    const fd = fs.openSync(path.join(STATE, "started"), fs.constants.O_WRONLY | fs.constants.O_NONBLOCK);
    fs.writeSync(fd, `${line}\n`);
    fs.closeSync(fd);
  } catch {
    // nobody waits for it
  }
}

/**
 * One file of each tsconfig project the repository tracks (outside node_modules), so
 * the server loads them before the first question needs them.
 */
function preloadFiles() {
  let files;
  try {
    files = execFileSync("git", ["ls-files", "-z", "--cached", "--others", "--exclude-standard"], { cwd: ROOT, maxBuffer: 1 << 28 }).toString().split("\0");
  } catch {
    return [];
  }
  const sources = files.filter((f) => /\.[cm]?tsx?$/.test(f) && !/\.d\.[cm]?ts$/.test(f) && !f.includes("node_modules/"));
  return files
    .filter((f) => /(^|\/)tsconfig\.json$/.test(f) && !f.includes("node_modules/"))
    .map((t) => {
      const dir = path.dirname(t) === "." ? "" : `${path.dirname(t)}/`;
      return sources.find((s) => s.startsWith(dir));
    })
    .filter((f, i, all) => f && all.indexOf(f) === i)
    .map((f) => path.join(ROOT, f));
}

async function main() {
  // detach: a session of its own, so ending the hook that started it does not end it
  if (!process.env.FORGE_TYPES_DETACHED) {
    spawn(process.execPath, process.argv.slice(1), { detached: true, stdio: "ignore", env: { ...process.env, FORGE_TYPES_DETACHED: "1" } }).unref();
    return;
  }
  fs.writeFileSync(path.join(STATE, "pid"), `${process.pid}\n`);
  const fd = fs.openSync(path.join(STATE, "in"), fs.constants.O_RDWR);
  const ts = projectTypeScript();
  const server = ts.major >= 7 ? new Lsp(ts) : new TsServer(ts);
  const ready = await server.start();
  fs.writeFileSync(path.join(STATE, "ready"), `${ready}\n`);
  log("started", ready, "for", ROOT);
  started(`ready ${ready}`);
  const types = new Types(server);
  // "stop<TAB><dir>": answered in <dir>/reply once the server has exited
  const stop = (why, dir) => {
    log("exiting:", why);
    cleanup();
    server.proc.removeAllListeners("exit");
    const done = () => {
      if (dir) reply(dir, []);
      process.exit(0);
    };
    if (server.proc.exitCode !== null || server.proc.signalCode !== null) done();
    server.proc.once("exit", done);
    setTimeout(() => server.proc.kill("SIGKILL"), 5000).unref();
    server.proc.kill();
  };
  // one job at a time: the FIFO's lines in order, the preload when there is none
  const lines = [];
  const preload = preloadFiles().map((file) => async () => {
    const t = performance.now();
    server.sync(file);
    await server.typeDefinition(file, { line: 0, character: 0 });
    log(`loaded the project of ${path.relative(ROOT, file)} in ${(performance.now() - t).toFixed(0)} ms`);
  });
  // while projects load, "loading" tells the hooks a question may wait for one (§15.3)
  const loading = path.join(STATE, "loading");
  if (preload.length) fs.writeFileSync(loading, `${preload.length}\n`);
  let running = false;
  const pump = () => {
    if (running) return;
    if (!preload.length) fs.rmSync(loading, { force: true });
    const job = lines.length ? lines.shift() : preload.shift();
    if (!job) return;
    running = true;
    Promise.resolve()
      .then(job)
      .catch((e) => log("error", e.stack ?? e))
      .finally(() => {
        running = false;
        pump();
      });
  };
  let idle = setTimeout(() => stop("idle"), IDLE);
  // the state directory was dropped (its FIFO gone or replaced), another daemon took it
  // over (its pid file names that one: a start whose starter was killed can race with the
  // next start, and both open the same FIFO) or the repository is gone: nobody reaches
  // this daemon any more
  const inode = fs.fstatSync(fd).ino;
  setInterval(() => {
    let gone;
    try {
      gone = fs.readFileSync(path.join(STATE, "pid"), "utf8").trim() !== String(process.pid) || fs.statSync(path.join(STATE, "in")).ino !== inode || !fs.existsSync(ROOT);
    } catch {
      gone = true;
    }
    if (gone) {
      log("orphaned, exiting");
      server.proc.removeAllListeners("exit");
      server.proc.kill();
      process.exit(0);
    }
  }, 10_000).unref();
  let buf = "";
  const stream = fs.createReadStream(null, { fd, autoClose: false, encoding: "utf8" });
  stream.on("data", (chunk) => {
    clearTimeout(idle);
    idle = setTimeout(() => stop("idle"), IDLE);
    buf += chunk;
    for (let i; (i = buf.indexOf("\n")) >= 0; ) {
      const line = buf.slice(0, i);
      buf = buf.slice(i + 1);
      lines.push(() => {
        if (line.startsWith("changed\t")) server.changed(path.join(ROOT, line.slice(8)));
        else if (line === "stop" || line === "restart") stop(`asked to ${line}`);
        else if (line.startsWith("stop\t")) stop("asked to stop", line.slice(5));
        else if (line.startsWith("/")) return question(types, line);
      });
    }
    pump();
  });
  pump();
}

async function question(types, dir) {
  const req = readText(path.join(dir, "req"));
  if (req === undefined) return;
  const matches = [];
  const raw = [];
  const out = [];
  for (const l of req.split("\n")) {
    if (!l) continue;
    try {
      matches.push(JSON.parse(l));
      raw.push(l);
    } catch {
      out.push(`error\tunreadable match: ${l.slice(0, 80)}`);
    }
  }
  const t = performance.now();
  try {
    for (const n of await answer(types, matches)) out.push(raw[n]);
  } catch (e) {
    log("error", e.stack ?? e);
    out.push(`error\t${e.message ?? e}`);
  }
  log(`answered ${matches.length} matches in ${(performance.now() - t).toFixed(1)} ms`);
  reply(dir, out);
}

main().catch((e) => {
  log("failed", e.stack ?? e);
  started(`failed ${e.message ?? e}`);
  cleanup();
  process.exit(2);
});
